//! Win32 bindings generated by build.rs from the names in windows-bindings.txt,
//! plus small helpers and constants the bundled metadata lacks.

// Win32 names keep their SDK spelling.
#![allow(non_upper_case_globals)]

#[allow(
    non_camel_case_types,
    non_snake_case,
    clippy::all,
    clippy::undocumented_unsafe_blocks
)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/windows_bindings.rs"));
}
pub use generated::*;

use windows_core::{Error, GUID, IUnknown, Result};

impl HANDLE {
    /// The handle, or the thread's last error if the call that produced it returned null.
    pub fn ok(self) -> Result<Self> {
        if self.0.is_null() {
            Err(Error::from_thread())
        } else {
            Ok(self)
        }
    }
}

impl HINSTANCE {
    /// The module, or the thread's last error if the call that produced it returned null.
    pub fn ok(self) -> Result<Self> {
        if self.0.is_null() {
            Err(Error::from_thread())
        } else {
            Ok(self)
        }
    }
}

impl PROPVARIANT {
    /// Takes the interface out of a `VT_UNKNOWN` variant (such as a Media Foundation event
    /// value), then clears the variant so its own reference is released.
    pub fn into_unknown(mut self) -> Result<IUnknown> {
        // SAFETY: every PROPVARIANT starts with the tagged header; punkVal is only read when vt
        // says it holds an interface, and PropVariantClear releases what the variant owns.
        unsafe {
            let inner = &self.Anonymous.Anonymous;
            let unk = if inner.vt == VARTYPE(VT_UNKNOWN as u16) {
                (*inner.Anonymous.punkVal).clone()
            } else {
                None
            };
            let _ = PropVariantClear(&mut self);
            unk.ok_or_else(|| Error::from(E_NOINTERFACE))
        }
    }
}

